import React, { useState, useEffect, useContext } from 'react';
import { AuthContext } from '../../Context/AuthContext';
import './MyAccount.css';
import Button from '../../Components/Buttons/ButtonBuy';
import Modal from '../../Components/Modal/Modal';
import { updateProfile, changePassword, uploadAvatar } from '../../Services/ApiUserService';

const MyAccount = () => {
    const { user, refreshProfile } = useContext(AuthContext);

    const [form, setForm] = useState({
        name: '',
        surname: '',
        email: '',
        phone: '',
        avatar: null, // base64 or url
    });

    const [selectedFile, setSelectedFile] = useState(null); // new file to upload
    const [avatarPreview, setAvatarPreview] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    // Password change states
    const [showChangePassword, setShowChangePassword] = useState(false);
    const [pwd, setPwd] = useState({ current: '', new: '', confirm: '' });
    const [pwdLoading, setPwdLoading] = useState(false);

    // Modal
    const [modal, setModal] = useState({ visible: false, title: '', message: '' });

    useEffect(() => {
        if (user) {
            setForm({
                name: user.name || '',
                surname: user.surname || '',
                email: user.email || '',
                phone: user.phone || '',
                avatar: user.avatar || null,
            });
            setAvatarPreview(user.avatar || '');
        }
    }, [user]);

    const handleInput = (field) => (e) => {
        setForm((s) => ({ ...s, [field]: e.target.value }));
    };

    const handleAvatar = (e) => {
        const file = e.target.files?.[0];
        if (!file) return;
        if (!file.type.startsWith('image/')) return setError('Vui lòng chọn file ảnh hợp lệ.');
        setSelectedFile(file); // set new file
        const reader = new FileReader();
        reader.onload = () => {
            setAvatarPreview(reader.result);
            // do not set form.avatar yet, will upload on submit
        };
        reader.readAsDataURL(file);
    };

    const validateProfile = () => {
        // simple validations
        if (!form.name || form.name.trim().length < 2) return 'Họ phải ít nhất 2 ký tự.';
        if (!form.surname || form.surname.trim().length < 2) return 'Tên phải ít nhất 2 ký tự.';
        if (!/^[\w.-]+@[\w.-]+\.[A-Za-z]{2,}$/i.test(form.email)) return 'Định dạng email không hợp lệ.';
        if (form.phone) {
            const p = form.phone.trim().replace(/\s+/g, '');
            if (!/^0\d{9}$/.test(p)) return 'Số điện thoại phải bắt đầu bằng 0 và có 10 chữ số.';
        }
        return null;
    };

    const submitProfile = async (e) => {
        e.preventDefault();
        setError('');
        const v = validateProfile();
        if (v) return setError(v);
        setLoading(true);
        try {
            let avatarUrl = form.avatar; // current or uploaded
            if (selectedFile) {
                // upload new avatar
                await uploadAvatar(selectedFile);
                setSelectedFile(null); // clear after upload
                // refresh profile to get new avatar URL
                await refreshProfile();
                avatarUrl = user.avatar; // updated after refresh
            }
            const payload = { ...form, avatar: avatarUrl };
            const res = await updateProfile(payload);
            setModal({ visible: true, title: 'Cập nhật thành công', message: res?.message || 'Thông tin tài khoản đã được cập nhật.' });
            // refresh context profile
            refreshProfile?.();
        } catch (err) {
            const det = err?.response?.data?.detail || err?.message || 'Có lỗi xảy ra';
            setError(typeof det === 'string' ? det : JSON.stringify(det));
        } finally {
            setLoading(false);
        }
    };

    const submitPassword = async (e) => {
        e.preventDefault();
        setError('');
        if (!pwd.current || !pwd.new) return setError('Vui lòng điền đầy đủ thông tin mật khẩu.');
        if (pwd.new.length < 6) return setError('Mật khẩu mới phải có ít nhất 6 ký tự.');
        if (pwd.new !== pwd.confirm) return setError('Mật khẩu xác nhận không khớp.');
        setPwdLoading(true);
        try {
            const res = await changePassword({ current_password: pwd.current, new_password: pwd.new });
            setModal({ visible: true, title: 'Thành công', message: res?.message || 'Mật khẩu đã được thay đổi.' });
            setPwd({ current: '', new: '', confirm: '' });
        } catch (err) {
            const det = err?.response?.data?.detail || err?.message || 'Có lỗi xảy ra';
            setError(typeof det === 'string' ? det : JSON.stringify(det));
        } finally {
            setPwdLoading(false);
        }
    };

    return (
        <>
            <div className="card mb-4 shadow-sm">
                <div className="card-body">
                    <div className="profile-header d-flex align-items-center">
                        <div className="avatar-wrapper">
                            <img src={avatarPreview || '/placeholder-avatar.png'} alt="avatar" className="avatar" />
                            <label className="upload-btn">
                                <input type="file" accept="image/*" onChange={handleAvatar} />
                                Thay ảnh
                            </label>
                        </div>
                        <div className="profile-meta">
                            <h3 className="display-name">{form.surname} {form.name}</h3>
                            <p className="muted">Cập nhật thông tin tài khoản để bảo mật và cá nhân hóa trải nghiệm</p>
                        </div>
                    </div>
                </div>
            </div>

            <div className="card mb-4 shadow-sm">
                <div className="card-body">
                    <h5 className="card-title mb-3">Thông tin cá nhân</h5>
                    <form className="profile-form" onSubmit={submitProfile}>
                        {error && <div className="alert alert-danger small">{error}</div>}

                        <div className="row gx-3">
                            <div className="col-md-6">
                                <label className="form-label">👤 Họ</label>
                                <input className="form-control" value={form.name} onChange={handleInput('name')} />
                            </div>
                            <div className="col-md-6">
                                <label className="form-label">👤 Tên</label>
                                <input className="form-control" value={form.surname} onChange={handleInput('surname')} />
                            </div>
                        </div>

                        <div className="row gx-3 mt-3">
                            <div className="col-md-6">
                                <label className="form-label">📧 Email</label>
                                <input className="form-control" type="email" value={form.email} onChange={handleInput('email')} />
                            </div>
                            <div className="col-md-6">
                                <label className="form-label">📱 Số điện thoại</label>
                                <input className="form-control" value={form.phone || ''} onChange={handleInput('phone')} />
                            </div>
                        </div>

                        <div className="d-flex justify-content-end gap-2 mt-4">
                            <Button type="button" className="btn-outline" onClick={() => { setForm({ name: user.name || '', surname: user.surname || '', email: user.email || '', phone: user.phone || '', avatar: user.avatar || null }); setAvatarPreview(user.avatar || ''); }}>Hoàn tác</Button>
                            <Button className="save-btn" type="submit" disabled={loading}>
                                {loading ? (
                                    <>
                                        <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                                        Đang lưu...
                                    </>
                                ) : (
                                    '💾 Lưu thay đổi'
                                )}
                            </Button>
                        </div>
                    </form>
                </div>
            </div>

            <div className="card shadow-sm">
                <div className="card-body">
                    <div className="password-section">
                        <div className="d-flex align-items-center justify-content-between">
                            <h5>Thay đổi mật khẩu</h5>
                            <button className="btn btn-link" onClick={() => setShowChangePassword(s => !s)}>{showChangePassword ? 'Hủy' : 'Đổi mật khẩu'}</button>
                        </div>

                        {showChangePassword && (
                            <form onSubmit={submitPassword} className="mt-3">
                                <div className="mb-3">
                                    <label className="form-label">🔒 Mật khẩu hiện tại</label>
                                    <input type="password" className="form-control" value={pwd.current} onChange={(e) => setPwd(p => ({ ...p, current: e.target.value }))} />
                                </div>
                                <div className="mb-3">
                                    <label className="form-label">🔑 Mật khẩu mới</label>
                                    <input type="password" className="form-control" value={pwd.new} onChange={(e) => setPwd(p => ({ ...p, new: e.target.value }))} />
                                </div>
                                <div className="mb-3">
                                    <label className="form-label">✅ Xác nhận mật khẩu mới</label>
                                    <input type="password" className="form-control" value={pwd.confirm} onChange={(e) => setPwd(p => ({ ...p, confirm: e.target.value }))} />
                                </div>
                                <div className="d-flex justify-content-end gap-2">
                                    <Button type="button" className="btn-outline" onClick={() => setShowChangePassword(false)}>Hủy</Button>
                                    <Button className="save-btn" type="submit" disabled={pwdLoading}>
                                        {pwdLoading ? (
                                            <>
                                                <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                                                Đang đổi...
                                            </>
                                        ) : (
                                            '🔄 Đổi mật khẩu'
                                        )}
                                    </Button>
                                </div>
                            </form>
                        )}
                    </div>
                </div>
            </div>

            <Modal visible={modal.visible} title={modal.title} message={modal.message} type="success" onClose={() => setModal({ visible: false })} showConfirm={false} />
        </>
    );
};

export default MyAccount;
